using GPR202_Assessment3;using OpenTK.Mathematics;
var p=new ParticleSystem();p.Explode(new Vector3(1,2,3));if(p.Count!=256)throw new Exception("Burst missing");p.Update(1f/120);if(p.Particles[0].Position==new Vector3(1,2,3))throw new Exception("Particles must move");for(int i=0;i<360;i++){p.Update(1f/120);for(int j=0;j<p.Count;j++)if(!float.IsFinite(p.Particles[j].Position.Y))throw new Exception("Invalid particle");}if(p.Count!=0)throw new Exception("Particles outlive restart");p.Explode(Vector3.Zero);p.Clear();if(p.Count!=0)throw new Exception("Restart must clear particles");Console.WriteLine("PASS burst, motion, expiration and reset.");
var fireworks=new VictoryFireworks();fireworks.Start();fireworks.Update(0.01f,Vector3.Zero,-Vector3.UnitZ,Vector3.Zero);if(fireworks.Bursts.Count(b=>b.Count>0)!=1)throw new Exception("First burst timing");for(int i=0;i<60;i++)fireworks.Update(1f/120,Vector3.Zero,-Vector3.UnitZ,Vector3.Zero);if(fireworks.Bursts.Count(b=>b.Count>0)!=2)throw new Exception("Staggered bursts");for(int i=0;i<720;i++)fireworks.Update(1f/120,Vector3.Zero,-Vector3.UnitZ,Vector3.Zero);if(fireworks.Bursts.Any(b=>b.Count>0))throw new Exception("Fireworks must finish");fireworks.Start();fireworks.Update(0.01f,Vector3.Zero,Vector3.UnitY,Vector3.Zero);fireworks.Clear();if(fireworks.Bursts.Any(b=>b.Count>0))throw new Exception("Restart cleanup");Console.WriteLine("PASS staggered fireworks, completion and reset.");
